import{_ as t,o as i,c as l,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"दस्तावेज़ संस्करण एवं अनुरक्षण टिप्पणियाँ","description":"","frontmatter":{},"headers":[],"relativePath":"hi/99-文档版本与维护说明.md","filePath":"hi/99-文档版本与维护说明.md","lastUpdated":null}'),r={name:"hi/99-文档版本与维护说明.md"};function o(h,a,d,n,u,s){return i(),l("div",null,[...a[0]||(a[0]=[e('<h1 id="दस्तावेज़-संस्करण-एवं-अनुरक्षण-टिप्पणियाँ" tabindex="-1">दस्तावेज़ संस्करण एवं अनुरक्षण टिप्पणियाँ <a class="header-anchor" href="#दस्तावेज़-संस्करण-एवं-अनुरक्षण-टिप्पणियाँ" aria-label="Permalink to &quot;दस्तावेज़ संस्करण एवं अनुरक्षण टिप्पणियाँ&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ क्रमांक</td><td>99</td></tr><tr><td>मॉड्यूल</td><td>परिशिष्ट एवं संदर्भ सामग्री</td></tr><tr><td>मुख्य कीवर्ड</td><td>संस्करण-प्रबंधन, अनुरक्षण टिप्पणियाँ, दस्तावेज़ मानक, अद्यतन-लॉग, सेटिंग अनुरक्षण</td></tr></tbody></table><h2 id="i-दस्तावेज़-प्रणाली-का-समग्र-परिचय" tabindex="-1">I. दस्तावेज़ प्रणाली का समग्र परिचय <a class="header-anchor" href="#i-दस्तावेज़-प्रणाली-का-समग्र-परिचय" aria-label="Permalink to &quot;I. दस्तावेज़ प्रणाली का समग्र परिचय&quot;">​</a></h2><p>लंगर सहजीवी सभ्यता की सेटिंग प्रणाली 100 मार्कडाउन दस्तावेज़ों से बनी है, जो 00 से 99 तक क्रमांकित हैं और दस बड़े मॉड्यूलों में विभाजित हैं, प्रत्येक मॉड्यूल में 10 दस्तावेज़ हैं। दस्तावेज़ प्रणाली SPEC.md (दस्तावेज़-निर्माण विनिर्देश) को कठोर बाधा मानती है, &quot;00-हेंग युआनझोउ: ब्रह्मांड अवलोकन&quot; को सामान्य रूपरेखा मानती है, प्रत्येक मॉड्यूल के दस्तावेज़ों को विभिन्न आयामों से विस्तृत करती है, और अंततः परिशिष्ट दस्तावेज़ों 90–99 का उपयोग अनुक्रमण, संकलन एवं व्यवस्था हेतु करती है। सम्पूर्ण दस्तावेज़ प्रणाली एक तार्किक रूप से स्व-संगत, स्पष्ट रूप से स्तरीकृत एवं परस्पर-संदर्भित पूर्ण सेटिंग ज्ञान-कोश का निर्माण करती है।</p><p>दस्तावेज़ प्रणाली का अभिकल्पन तीन मूल सिद्धांतों का पालन करता है: &quot;मॉड्यूलरता, संरचनात्मकता, विस्तारणीयता&quot;। मॉड्यूलरता का अर्थ है कि प्रत्येक दस्तावेज़ एक विशिष्ट विषय पर केंद्रित होकर स्वतंत्र लेख के रूप में रहता है; संरचनात्मकता का अर्थ है कि सभी दस्तावेज़ पठन एवं खोज की सुविधा हेतु एक समान प्रारूप-विनिर्देश का पालन करते हैं; विस्तारणीयता का अर्थ है कि दस्तावेज़ प्रणाली विस्तार हेतु पर्याप्त स्थान आरक्षित करती है, मौजूदा दस्तावेज़ों के संशोधन एवं नई सामग्री के परिवर्धन के माध्यम से सेटिंग्स का निरंतर परिष्कार संभव है।</p><h2 id="ii-संस्करण-क्रमांकन-नियम" tabindex="-1">II. संस्करण-क्रमांकन नियम <a class="header-anchor" href="#ii-संस्करण-क्रमांकन-नियम" aria-label="Permalink to &quot;II. संस्करण-क्रमांकन नियम&quot;">​</a></h2><p>दस्तावेज़ प्रणाली त्रि-स्तरीय संस्करण-क्रमांकन नियम &quot;मुख्य-संस्करण.गौण-संस्करण.संशोधन-संख्या&quot; अपनाती है:</p><table tabindex="0"><thead><tr><th>संस्करण-स्तर</th><th>क्रमांकन नियम</th><th>ट्रिगर-शर्त</th><th>उदाहरण</th></tr></thead><tbody><tr><td>मुख्य-संस्करण</td><td>1 से बढ़ता है</td><td>दस्तावेज़ प्रणाली में बड़ा संरचनात्मक परिवर्तन, जैसे मॉड्यूलों का पुनर्विभाजन या मूल सेटिंग्स का परिवर्तन</td><td>v1.0 → v2.0</td></tr><tr><td>गौण-संस्करण</td><td>0 से बढ़ता है</td><td>किसी दस्तावेज़ की मूल सामग्री में आवश्यक संशोधन, या महत्वपूर्ण नई सेटिंग सामग्री का परिवर्धन</td><td>v1.0 → v1.1</td></tr><tr><td>संशोधन-संख्या</td><td>0 से बढ़ती है</td><td>पाठ-सुधार, प्रारूप-समायोजन, शब्दावली-एकीकरण जैसे गैर-आवश्यक संशोधन</td><td>v1.0 → v1.0.1</td></tr></tbody></table><p>दस्तावेज़ प्रणाली का वर्तमान समग्र संस्करण v1.0 है, अर्थात् प्रथम पूर्ण प्रकाशन संस्करण। प्रत्येक दस्तावेज़ अपने दस्तावेज़-सूचना खंड में अपना संस्करण-संख्या अंकित करता है, और दस्तावेज़ प्रणाली की समग्र संस्करण-संख्या इसी दस्तावेज़ में एकीकृत रूप से अंकित होती है।</p><h2 id="iii-दस्तावेज़-प्रारूप-विनिर्देशों-की-समीक्षा" tabindex="-1">III. दस्तावेज़ प्रारूप विनिर्देशों की समीक्षा <a class="header-anchor" href="#iii-दस्तावेज़-प्रारूप-विनिर्देशों-की-समीक्षा" aria-label="Permalink to &quot;III. दस्तावेज़ प्रारूप विनिर्देशों की समीक्षा&quot;">​</a></h2><p>सभी दस्तावेज़ों को निम्नलिखित एकीकृत प्रारूप विनिर्देशों का पालन करना होगा (विस्तृत विनिर्देश हेतु SPEC.md देखें):</p><h3 id="_3-1-फ़ाइल-नामकरण" tabindex="-1">3.1 फ़ाइल नामकरण <a class="header-anchor" href="#_3-1-फ़ाइल-नामकरण" aria-label="Permalink to &quot;3.1 फ़ाइल नामकरण&quot;">​</a></h3><p>फ़ाइल-नाम प्रारूप <code>XX-दस्तावेज़ शीर्षक.md</code> है, जहाँ XX 00–99 का दो-अंकीय क्रमांक है, और शीर्षक बिना रिक्त-स्थान के चीनी भाषा में होता है।</p><h3 id="_3-2-दस्तावेज़-संरचना" tabindex="-1">3.2 दस्तावेज़ संरचना <a class="header-anchor" href="#_3-2-दस्तावेज़-संरचना" aria-label="Permalink to &quot;3.2 दस्तावेज़ संरचना&quot;">​</a></h3><p>प्रत्येक दस्तावेज़ में निम्नलिखित संरचनात्मक तत्व अनिवार्य रूप से शामिल होने चाहिए:</p><ol><li><strong>प्रथम-स्तरीय शीर्षक</strong>: दस्तावेज़ शीर्षक (फ़ाइल-नाम से संगत)</li><li><strong>दस्तावेज़ सूचना खंड</strong>: क्रमांक, मॉड्यूल, मुख्य कीवर्ड (3–5) की तालिका</li><li><strong>मुख्य पाठ</strong>: कम से कम 3 द्वितीय-स्तरीय शीर्षक खंड, सूचियों एवं तालिकाओं जैसे संरचनात्मक तत्वों का उपयोग करते हुए</li><li><strong>उपसंहार</strong>: संक्षिप्त सारांश अनुच्छेद</li><li><strong>संबंधित दस्तावेज़</strong>: 2–3 संबंधित दस्तावेज़ क्रमांक एवं नामों की सूची</li></ol><h3 id="_3-3-शब्द-संख्या-आवश्यकता" tabindex="-1">3.3 शब्द-संख्या आवश्यकता <a class="header-anchor" href="#_3-3-शब्द-संख्या-आवश्यकता" aria-label="Permalink to &quot;3.3 शब्द-संख्या आवश्यकता&quot;">​</a></h3><p>प्रत्येक दस्तावेज़ का मुख्य पाठ 800 शब्दों से कम नहीं होना चाहिए (शीर्षक एवं मेटा-सूचना को छोड़कर)।</p><h3 id="_3-4-लेखन-शैली" tabindex="-1">3.4 लेखन-शैली <a class="header-anchor" href="#_3-4-लेखन-शैली" aria-label="Permalink to &quot;3.4 लेखन-शैली&quot;">​</a></h3><ul><li>गंभीर, व्यवस्थित सेटिंग-दस्तावेज़ शैली, विश्वकोश/सेटिंग-संग्रह के समान</li><li>&quot;हेंग-ब्रह्मांड&quot;, &quot;लंगर&quot;, &quot;सहजीवन&quot; जैसे एकीकृत शब्दों का उपयोग</li><li>नई जोड़ी गई सेटिंग्स मौजूदा सेटिंग्स के साथ तार्किक रूप से स्व-संगत होनी चाहिए और &quot;वास्तविकता-आधार, नियम-उन्नयन&quot; सिद्धांत के अनुरूप होनी चाहिए</li></ul><h2 id="iv-अनुरक्षण-संगठन-एवं-उत्तरदायित्व" tabindex="-1">IV. अनुरक्षण संगठन एवं उत्तरदायित्व <a class="header-anchor" href="#iv-अनुरक्षण-संगठन-एवं-उत्तरदायित्व" aria-label="Permalink to &quot;IV. अनुरक्षण संगठन एवं उत्तरदायित्व&quot;">​</a></h2><h3 id="_4-1-सेटिंग-अनुरक्षण-समिति" tabindex="-1">4.1 सेटिंग अनुरक्षण समिति <a class="header-anchor" href="#_4-1-सेटिंग-अनुरक्षण-समिति" aria-label="Permalink to &quot;4.1 सेटिंग अनुरक्षण समिति&quot;">​</a></h3><p>सेटिंग अनुरक्षण समिति दस्तावेज़ प्रणाली की सर्वोच्च अनुरक्षण संस्था है, जो वरिष्ठ सेटिंग-रचनाकारों, तर्क-सत्यापन विशेषज्ञों एवं उपयोगकर्ता प्रतिनिधियों से बनी है। इसके मूल उत्तरदायित्वों में शामिल हैं:</p><ul><li>दस्तावेज़ प्रणाली की समग्र संरचना एवं बड़ी संशोधन योजनाओं का अनुमोदन</li><li>प्रमुख सेटिंग परिवर्तनों की समीक्षा, मूल सेटिंग्स के साथ संगति सुनिश्चित करना</li><li>सेटिंग विवादों का निर्णय एवं प्रामाणिक व्याख्या देना</li><li>नियमित रूप से व्यापक सेटिंग-संगति स्व-जाँच का आयोजन</li><li>दस्तावेज़ प्रणाली के समग्र संस्करण-अद्यतनों का प्रकाशन</li></ul><h3 id="_4-2-मॉड्यूल-अनुरक्षक" tabindex="-1">4.2 मॉड्यूल अनुरक्षक <a class="header-anchor" href="#_4-2-मॉड्यूल-अनुरक्षक" aria-label="Permalink to &quot;4.2 मॉड्यूल अनुरक्षक&quot;">​</a></h3><p>प्रत्येक मॉड्यूल एक मॉड्यूल अनुरक्षक नियुक्त करता है, जो उस मॉड्यूल के 10 दस्तावेज़ों के दैनिक अनुरक्षण हेतु उत्तरदायी है। उनके उत्तरदायित्वों में शामिल हैं:</p><ul><li>मॉड्यूल के दस्तावेज़ों की सेटिंग-संगति पर अनुश्रवण</li><li>मॉड्यूल के दस्तावेज़ों के संशोधन-आवेदनों की समीक्षा</li><li>मॉड्यूल के दस्तावेज़ों के बीच परस्पर-संदर्भों का समन्वय</li><li>मॉड्यूल सामग्री पर उपयोगकर्ता प्रतिक्रिया एवं सुझाव एकत्र करना</li><li>नियमित रूप से सेटिंग अनुरक्षण समिति को मॉड्यूल अनुरक्षण-स्थिति की रिपोर्ट देना</li></ul><h3 id="_4-3-दस्तावेज़-रचनाकार" tabindex="-1">4.3 दस्तावेज़ रचनाकार <a class="header-anchor" href="#_4-3-दस्तावेज़-रचनाकार" aria-label="Permalink to &quot;4.3 दस्तावेज़ रचनाकार&quot;">​</a></h3><p>कोई भी योग्य रचनाकार दस्तावेज़ों के निर्माण एवं संशोधन में भाग ले सकता है। रचनाकारों के उत्तरदायित्वों में शामिल हैं:</p><ul><li>प्रारूप-विनिर्देशों के अनुसार दस्तावेज़ों का निर्माण या संशोधन</li><li>यह सुनिश्चित करना कि निर्मित सामग्री सेटिंग विरोधाभास स्व-जाँच सूची की जाँच उत्तीर्ण करे</li><li>संशोधन प्रस्तुत करते समय विस्तृत संशोधन-विवरण संलग्न करना</li><li>अनुरक्षकों एवं समिति की समीक्षा-कार्य में सहयोग</li></ul><h2 id="v-संशोधन-प्रक्रिया" tabindex="-1">V. संशोधन प्रक्रिया <a class="header-anchor" href="#v-संशोधन-प्रक्रिया" aria-label="Permalink to &quot;V. संशोधन प्रक्रिया&quot;">​</a></h2><h3 id="_5-1-सामान्य-संशोधन-प्रक्रिया" tabindex="-1">5.1 सामान्य संशोधन प्रक्रिया <a class="header-anchor" href="#_5-1-सामान्य-संशोधन-प्रक्रिया" aria-label="Permalink to &quot;5.1 सामान्य संशोधन प्रक्रिया&quot;">​</a></h3><ol><li><strong>आवेदन प्रस्तुत करना</strong>: रचनाकार मॉड्यूल अनुरक्षक को संशोधन-आवेदन प्रस्तुत करता है, जिसमें संशोधित होने वाले दस्तावेज़ क्रमांक, संशोधन-सामग्री का विवरण एवं संशोधन-कारण शामिल होते हैं।</li><li><strong>मॉड्यूल समीक्षा</strong>: मॉड्यूल अनुरक्षक संशोधन-सामग्री की समीक्षा करता है, मुख्य रूप से प्रारूप-विनिर्देशों एवं मॉड्यूल-आंतरिक संगति की जाँच करता है। अनुमोदन के बाद सेटिंग अनुरक्षण समिति को प्रस्तुत किया जाता है।</li><li><strong>समिति अनुमोदन</strong>: सेटिंग अनुरक्षण समिति संशोधन-सामग्री का अंतिम अनुमोदन करती है, मुख्य रूप से अंतर-मॉड्यूल संगति एवं मूल-सेटिंग संगति की जाँच करती है।</li><li><strong>संशोधन क्रियान्वयन</strong>: अनुमोदन के बाद, मॉड्यूल अनुरक्षक या मूल लेखक दस्तावेज़ संशोधन क्रियान्वित करता है।</li><li><strong>संस्करण-अद्यतन</strong>: संशोधन पूर्ण होने पर, दस्तावेज़ संस्करण-संख्या अद्यतन करें और इस दस्तावेज़ के अद्यतन-लॉग में अंकित करें।</li><li><strong>संबंधित-संकालन</strong>: यदि संशोधन-सामग्री अन्य दस्तावेज़ों को प्रभावित करती है, तो संबंधित दस्तावेज़ों का भी समकालिक संशोधन आवश्यक है।</li></ol><h3 id="_5-2-आपातकालीन-संशोधन-प्रक्रिया" tabindex="-1">5.2 आपातकालीन संशोधन प्रक्रिया <a class="header-anchor" href="#_5-2-आपातकालीन-संशोधन-प्रक्रिया" aria-label="Permalink to &quot;5.2 आपातकालीन संशोधन प्रक्रिया&quot;">​</a></h3><p>गंभीर सेटिंग विरोधाभास या त्रुटियाँ मिलने जैसी आपात स्थितियों हेतु, आपातकालीन संशोधन प्रक्रिया शुरू की जा सकती है:</p><ol><li><strong>आपात-रिपोर्ट</strong>: खोजकर्ता तुरंत समस्या की रिपोर्ट सेटिंग अनुरक्षण समिति को करता है।</li><li><strong>शीघ्र अनुमोदन</strong>: समिति 24 घंटों के भीतर आपातकालीन अनुमोदन पूर्ण करती है और संशोधन-योजना देती है।</li><li><strong>संशोधन क्रियान्वयन</strong>: तत्काल क्रियान्वयन हेतु विशेष व्यक्ति नियुक्त किया जाता है।</li><li><strong>पश्चात्-अभिलेखन</strong>: संशोधन पूर्ण होने के बाद, संशोधन-आवेदन एवं समीक्षा-अभिलेख पूर्वव्यापी रूप से दर्ज किए जाते हैं।</li></ol><h3 id="_5-3-आवधिक-व्यापक-संशोधन" tabindex="-1">5.3 आवधिक व्यापक संशोधन <a class="header-anchor" href="#_5-3-आवधिक-व्यापक-संशोधन" aria-label="Permalink to &quot;5.3 आवधिक व्यापक संशोधन&quot;">​</a></h3><p>सेटिंग अनुरक्षण समिति प्रतिवर्ष एक बार दस्तावेज़ प्रणाली का व्यापक संशोधन आयोजित करती है, जिसमें शामिल हैं:</p><ul><li>व्यापक सेटिंग-संगति स्व-जाँच</li><li>उपयोगकर्ता प्रतिक्रिया का केंद्रीकृत निपटान</li><li>शब्दावली प्रणाली का एकीकरण एवं अद्यतन</li><li>अनुक्रमणिका दस्तावेज़ों का समकालिक अद्यतन</li><li>दस्तावेज़ प्रारूपों की एकीकृत जाँच एवं सुधार</li></ul><h2 id="vi-अद्यतन-लॉग" tabindex="-1">VI. अद्यतन-लॉग <a class="header-anchor" href="#vi-अद्यतन-लॉग" aria-label="Permalink to &quot;VI. अद्यतन-लॉग&quot;">​</a></h2><h3 id="v1-0-प्रथम-पूर्ण-प्रकाशन" tabindex="-1">v1.0 (प्रथम पूर्ण प्रकाशन) <a class="header-anchor" href="#v1-0-प्रथम-पूर्ण-प्रकाशन" aria-label="Permalink to &quot;v1.0 (प्रथम पूर्ण प्रकाशन)&quot;">​</a></h3><ul><li>सभी 100 दस्तावेज़ों का निर्माण एवं प्रकाशन पूर्ण</li><li>पूर्ण दस्तावेज़ प्रणाली संरचना एवं प्रारूप-विनिर्देश स्थापित</li><li>दस बड़े मॉड्यूलों की सामग्री-कवरेज पूर्ण</li><li>परिशिष्ट अनुक्रमण प्रणाली स्थापित (शब्दावली-कोश, प्रणाली अनुक्रमणिका, कानून अनुक्रमणिका, इतिवृत्त, दस हजार जातियों की नामावली, व्यक्तित्व-संगठन, FAQ, स्व-जाँच सूची, विस्तार-सुझाव, संस्करण-टिप्पणियाँ)</li></ul><h3 id="बाद-के-संस्करण-अद्यतन-अभिलेख-क्षेत्र" tabindex="-1">बाद के संस्करण अद्यतन-अभिलेख क्षेत्र <a class="header-anchor" href="#बाद-के-संस्करण-अद्यतन-अभिलेख-क्षेत्र" aria-label="Permalink to &quot;बाद के संस्करण अद्यतन-अभिलेख क्षेत्र&quot;">​</a></h3><p>(बाद के संस्करणों की अद्यतन सामग्री यहाँ जोड़ी जाएगी, जिसमें संस्करण-संख्या, प्रकाशन-तिथि एवं मुख्य अद्यतन-सामग्री का सारांश शामिल होगा)</p><h2 id="vii-दस्तावेज़-उद्धरण-एवं-परस्पर-संदर्भ-विनिर्देश" tabindex="-1">VII. दस्तावेज़ उद्धरण एवं परस्पर-संदर्भ विनिर्देश <a class="header-anchor" href="#vii-दस्तावेज़-उद्धरण-एवं-परस्पर-संदर्भ-विनिर्देश" aria-label="Permalink to &quot;VII. दस्तावेज़ उद्धरण एवं परस्पर-संदर्भ विनिर्देश&quot;">​</a></h2><h3 id="_7-1-आंतरिक-उद्धरण" tabindex="-1">7.1 आंतरिक उद्धरण <a class="header-anchor" href="#_7-1-आंतरिक-उद्धरण" aria-label="Permalink to &quot;7.1 आंतरिक उद्धरण&quot;">​</a></h3><p>दस्तावेज़ों के बीच परस्पर-संदर्भ &quot;दस्तावेज़ क्रमांक-दस्तावेज़ शीर्षक&quot; प्रारूप का उपयोग करते हैं, उदाहरणार्थ &quot;दस्तावेज़ 84 &#39;पुरातत्व प्रोटोकॉल सामान्य ढाँचा&#39; देखें&quot;। उद्धरण करते समय यह सुनिश्चित करना चाहिए कि उद्धृत दस्तावेज़ वास्तव में विद्यमान है तथा क्रमांक एवं शीर्षक सही हैं।</p><h3 id="_7-2-शब्दावली-उद्धरण" tabindex="-1">7.2 शब्दावली उद्धरण <a class="header-anchor" href="#_7-2-शब्दावली-उद्धरण" aria-label="Permalink to &quot;7.2 शब्दावली उद्धरण&quot;">​</a></h3><p>किसी मूल शब्द के प्रथम प्रयोग पर, दस्तावेज़ 90 &quot;शब्दावली-कोश&quot; की संगत प्रविष्टि का संदर्भ दिया जा सकता है। उसी शब्द के बाद के प्रयोगों पर बार-बार संदर्भ देने की आवश्यकता नहीं है।</p><h3 id="_7-3-बाह्य-उद्धरण" tabindex="-1">7.3 बाह्य उद्धरण <a class="header-anchor" href="#_7-3-बाह्य-उद्धरण" aria-label="Permalink to &quot;7.3 बाह्य उद्धरण&quot;">​</a></h3><p>यदि सेटिंग प्रणाली के बाहर की वास्तविक सामग्री या काल्पनिक कृतियों का उद्धरण आवश्यक हो, तो स्रोत अंकित किया जाना चाहिए और स्पष्ट रूप से बताया जाना चाहिए कि यह उद्धरण &quot;वास्तविकता-आधार&quot; सिद्धांत के अंतर्गत संदर्भ-सामग्री है, और सेटिंग प्रणाली द्वारा उसकी सामग्री का पूर्ण स्वीकार नहीं दर्शाता।</p><h2 id="viii-गुणवत्ता-आश्वासन-तंत्र" tabindex="-1">VIII. गुणवत्ता-आश्वासन तंत्र <a class="header-anchor" href="#viii-गुणवत्ता-आश्वासन-तंत्र" aria-label="Permalink to &quot;VIII. गुणवत्ता-आश्वासन तंत्र&quot;">​</a></h2><h3 id="_8-1-सेटिंग-विरोधाभास-स्व-जाँच" tabindex="-1">8.1 सेटिंग विरोधाभास स्व-जाँच <a class="header-anchor" href="#_8-1-सेटिंग-विरोधाभास-स्व-जाँच" aria-label="Permalink to &quot;8.1 सेटिंग विरोधाभास स्व-जाँच&quot;">​</a></h3><p>सभी नवनिर्मित एवं संशोधित दस्तावेज़ों को दस्तावेज़ 97 &quot;सेटिंग विरोधाभास स्व-जाँच सूची&quot; के सभी जाँच-बिंदु उत्तीर्ण करने होंगे, जिसमें तीन बड़ी श्रेणियों की 40 से अधिक जाँचें शामिल हैं: मूल-सेटिंग संगति, अंतर-मॉड्यूल तार्किक संगति, दस्तावेज़ प्रारूप-विनिर्देश।</p><h3 id="_8-2-परस्पर-समीक्षा" tabindex="-1">8.2 परस्पर-समीक्षा <a class="header-anchor" href="#_8-2-परस्पर-समीक्षा" aria-label="Permalink to &quot;8.2 परस्पर-समीक्षा&quot;">​</a></h3><p>प्रत्येक दस्तावेज़ को औपचारिक प्रकाशन से पहले कम से कम एक अन्य रचनाकार की परस्पर-समीक्षा से गुजरना होगा, जिसमें मुख्य रूप से अंतर-मॉड्यूल तार्किक संगति एवं शब्दावली एकरूपता की जाँच होती है।</p><h3 id="_8-3-उपयोगकर्ता-प्रतिक्रिया-तंत्र" tabindex="-1">8.3 उपयोगकर्ता प्रतिक्रिया तंत्र <a class="header-anchor" href="#_8-3-उपयोगकर्ता-प्रतिक्रिया-तंत्र" aria-label="Permalink to &quot;8.3 उपयोगकर्ता प्रतिक्रिया तंत्र&quot;">​</a></h3><p>दस्तावेज़ प्रणाली उपयोगकर्ता प्रतिक्रिया चैनल स्थापित करती है; उपयोगकर्ता निम्नलिखित माध्यमों से प्रतिक्रिया प्रस्तुत कर सकते हैं:</p><ul><li>सेटिंग विरोधाभास एवं तार्किक त्रुटियों की रिपोर्ट</li><li>शब्दावली असामंजस्य की समस्याएँ उठाना</li><li>विशिष्ट सामग्री के परिवर्धन या संशोधन हेतु सुझाव</li><li>प्रारूप एवं पाठ त्रुटियों की ओर संकेत</li></ul><p>सभी प्रतिक्रियाओं को मॉड्यूल अनुरक्षक वर्गीकृत रूप से संसाधित करते हैं, और महत्वपूर्ण प्रतिक्रियाएँ सेटिंग अनुरक्षण समिति के विचारण हेतु प्रस्तुत की जाती हैं।</p><h3 id="_8-4-त्रैमासिक-संगति-रिपोर्ट" tabindex="-1">8.4 त्रैमासिक संगति रिपोर्ट <a class="header-anchor" href="#_8-4-त्रैमासिक-संगति-रिपोर्ट" aria-label="Permalink to &quot;8.4 त्रैमासिक संगति रिपोर्ट&quot;">​</a></h3><p>सेटिंग अनुरक्षण समिति प्रत्येक तिमाही एक &quot;सेटिंग संगति रिपोर्ट&quot; प्रकाशित करती है, जिसमें शामिल हैं:</p><ul><li>तिमाही में खोजे गए सेटिंग विरोधाभास एवं उनका निपटान</li><li>तिमाही के दस्तावेज़ संशोधन-सांख्यिकी</li><li>शब्दावली एकीकरण की प्रगति</li><li>उपयोगकर्ता प्रतिक्रिया का निपटान-स्थिति</li><li>अगली तिमाही की अनुरक्षण-योजना</li></ul><h2 id="ix-दस्तावेज़-संग्रहण-एवं-वितरण" tabindex="-1">IX. दस्तावेज़ संग्रहण एवं वितरण <a class="header-anchor" href="#ix-दस्तावेज़-संग्रहण-एवं-वितरण" aria-label="Permalink to &quot;IX. दस्तावेज़ संग्रहण एवं वितरण&quot;">​</a></h2><h3 id="_9-1-संग्रहण-प्रारूप" tabindex="-1">9.1 संग्रहण प्रारूप <a class="header-anchor" href="#_9-1-संग्रहण-प्रारूप" aria-label="Permalink to &quot;9.1 संग्रहण प्रारूप&quot;">​</a></h3><p>सभी दस्तावेज़ मार्कडाउन (.md) प्रारूप में संग्रहीत होते हैं, जो क्रॉस-प्लेटफ़ॉर्म पठनीयता एवं संस्करण-प्रबंधन की सुविधा सुनिश्चित करता है। दस्तावेज़ UTF-8 एन्कोडिंग का उपयोग करते हैं, जो चीनी एवं विशेष वर्णों का समर्थन करता है।</p><h3 id="_9-2-निर्देशिका-संरचना" tabindex="-1">9.2 निर्देशिका संरचना <a class="header-anchor" href="#_9-2-निर्देशिका-संरचना" aria-label="Permalink to &quot;9.2 निर्देशिका संरचना&quot;">​</a></h3><p>दस्तावेज़ एकीकृत रूप से <code>anchor-docs/</code> निर्देशिका में संग्रहीत होते हैं, फ़ाइल-नाम <code>XX-दस्तावेज़ शीर्षक.md</code> प्रारूप में होते हैं। SPEC.md, विनिर्देश-फ़ाइल के रूप में, उसी निर्देशिका में संग्रहीत है।</p><h3 id="_9-3-संस्करण-प्रबंधन" tabindex="-1">9.3 संस्करण-प्रबंधन <a class="header-anchor" href="#_9-3-संस्करण-प्रबंधन" aria-label="Permalink to &quot;9.3 संस्करण-प्रबंधन&quot;">​</a></h3><p>दस्तावेज़ों के संस्करण-प्रबंधन हेतु Git जैसी संस्करण-नियंत्रण प्रणालियों का उपयोग करने की अनुशंसा की जाती है; प्रत्येक संशोधन-प्रस्तुति पर विस्तृत commit message संलग्न करें, जिसमें संशोधन-सामग्री एवं कारण अंकित हों।</p><h3 id="_9-4-वितरण-विधियाँ" tabindex="-1">9.4 वितरण-विधियाँ <a class="header-anchor" href="#_9-4-वितरण-विधियाँ" aria-label="Permalink to &quot;9.4 वितरण-विधियाँ&quot;">​</a></h3><p>दस्तावेज़ प्रणाली निम्नलिखित माध्यमों से वितरित की जा सकती है:</p><ul><li>डाउनलोड हेतु ZIP संपीड़ित-संग्रह में पैक करना</li><li>ऑनलाइन देखने हेतु स्थैतिक वेबसाइट के रूप में परिनियोजन</li><li>पठन हेतु PDF या EPUB प्रारूप में रूपांतरण</li><li>संरचनात्मक प्रबंधन हेतु ज्ञान-कोश प्रणालियों में आयात</li></ul><h2 id="उपसंहार" tabindex="-1">उपसंहार <a class="header-anchor" href="#उपसंहार" aria-label="Permalink to &quot;उपसंहार&quot;">​</a></h2><p>दस्तावेज़ संस्करण एवं अनुरक्षण टिप्पणियाँ लंगर सहजीवी सभ्यता की सेटिंग प्रणाली का &quot;प्रशासनिक संविधान&quot; है। यह दस्तावेज़ प्रणाली के संस्करण-नियम, अनुरक्षण संगठन, संशोधन प्रक्रिया, गुणवत्ता-आश्वासन तंत्र एवं संग्रहण-वितरण विधियाँ स्थापित करता है, यह सुनिश्चित करते हुए कि 100 दस्तावेज़ों से बनी यह विराट सेटिंग प्रणाली निरंतर वृद्धि की प्रक्रिया में सदैव व्यवस्था एवं संगति बनाए रख सके। एक अच्छी सेटिंग प्रणाली के लिए केवल शानदार सामग्री ही नहीं, बल्कि उसके दीर्घकालिक स्वस्थ विकास की गारंटी हेतु परिपूर्ण अनुरक्षण तंत्र भी आवश्यक है। यह दस्तावेज़ उसी तंत्र का मूल वाहक है।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>97-设定矛盾自查表 (सेटिंग विरोधाभास स्व-जाँच सूची)</li><li>90-术语词典 (शब्दावली-कोश)</li><li>00-衡元宙宇宙总览 (हेंग युआनझोउ: ब्रह्मांड अवलोकन)</li></ul>',77)])])}const b=t(r,[["render",o]]);export{c as __pageData,b as default};
